class Solution {
    public: int numSubmatrixSumTarget(vector<vector<int>>& matrix,int target){
        int rows=matrix.size(),columns=matrix[0].size(),answer=0;
        for(int top=0;top<rows;++top){
            vector<int> sums(columns);
            for(int bottom=top;bottom<rows;++bottom){
                for(int c=0;c<columns;++c)sums[c]+=matrix[bottom][c];
                unordered_map<int,int> frequency{
                    {
                        0,1
                    }
                };
                int prefix=0;
                for(int value:sums){
                    prefix+=value;
                    answer+=frequency[prefix-target];
                    ++frequency[prefix];
                }
            }
        }
        return answer;
    }
};
